import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        uint beforeBalance = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(address(this), _value, bytes("")) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        assertTrue(!reverted && afterBalance + _value == beforeBalance && afterCount == beforeCount);
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
